  v_new text := $t$    when 'car_bought' then 'Neues Auto'
    when 'tax_penalty' then 'Strafe vom Finanzamt für ' || coalesce(p_payload ->> 'company', '?')
    when 'tax_audit' then 'Betriebsprüfung bei ' || coalesce(p_payload ->> 'company', '?')
    when 'greedy_founder' then 'zahlt sich bei ' || coalesce(p_payload ->> 'company', '?') || ' fast den ganzen Gewinn selbst aus'
    when 'mass_quit' then 'Kündigungswelle bei ' || coalesce(p_payload ->> 'company', '?')
    when 'record_dividend' then 'Rekorddividende bei ' || coalesce(p_payload ->> 'company', '?')
    when 'board_revolt' then 'Aufstand im Geschäftsrat von ' || coalesce(p_payload ->> 'company', '?')
    when 'research_done' then 'Forschungsdurchbruch bei ' || coalesce(p_payload ->> 'company', '?')$t$;
begin
  if position('greedy_founder' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'feed_item_label() has an unexpected shape; add the listed company feed kinds (ADR-167) by hand';
    end if;
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- NEXA Nachrichten: personal news from listed companies
do $do$
declare
  v_def  text := pg_get_functiondef('public.news_show_build(timestamptz)'::regprocedure);
  v_bad  text := $t$when f.kind in ('rug_pull', 'loan_defaulted', 'deal_broken', 'coin_closed')$t$;
  -- anchored without 'big_trade': the Nexamon migration puts 'nexamon_pull' between it and 'rug_pull'
  v_list text := $t$'rug_pull', 'loan_defaulted', 'deal_broken', 'coin_closed')$t$;
begin
  if position('greedy_founder' in v_def) = 0 then
    if position(v_bad in v_def) = 0 or position(v_list in v_def) = 0 then
      raise exception 'news_show_build() has an unexpected shape; add the listed company feed kinds (ADR-167) to the gossip source by hand';
    end if;
    v_def := replace(v_def, v_bad,
      $t$when f.kind in ('rug_pull', 'loan_defaulted', 'deal_broken', 'coin_closed', 'tax_penalty', 'tax_audit', 'greedy_founder', 'mass_quit')$t$);
    v_def := replace(v_def, v_list,
      $t$'rug_pull', 'loan_defaulted', 'deal_broken', 'coin_closed',
                                  'tax_penalty', 'tax_audit', 'greedy_founder', 'mass_quit', 'record_dividend', 'board_revolt')$t$);
    execute v_def;
  end if;
end;
$do$;

-- ===== supabase/migrations/20261204005500_nexamon_peak_prices.sql =====
-- =============================================================================
-- NEXA · 5500 · Nexamon: Prismatic Peak costs 10.000 €, its cards are worth 1.5x (ADR-165)
-- =============================================================================
-- The pack price and the start prices come from game_config (nexamon, nexamon_cards). nexamon_sync() moves the
-- start price of every card to the new catalogue, but the market value only of cards that never moved. So an
-- existing database gets one push here: start price, market value, the day's reference and the value history of
-- every Prismatic Peak card times 1.5, and the AI sellers' asking prices after it. Players' own listings keep the
-- price their owner chose. Runs once (nexamon_meta.peak_scaled_at); on a new database it only sets the mark.

alter table public.nexamon_meta add column if not exists peak_scaled_at timestamptz;
comment on column public.nexamon_meta.peak_scaled_at is
  'When the Prismatic Peak values were scaled by 1.5 for the 10.000 € pack (migration 5500); set once.';

do $$
begin
  if exists (select 1 from public.nexamon_meta m where m.peak_scaled_at is not null) then
    return;
  end if;

  update public.nexamon_cards k
     set start_e4   = public.div_round_half_even(k.start_e4::numeric * 3, 2),
         value_e4   = public.div_round_half_even(k.value_e4::numeric * 3, 2),
         day_ref_e4 = public.div_round_half_even(k.day_ref_e4::numeric * 3, 2),
         updated_at = now()
   where k.set_key = 'prismatic_peak';

  update public.nexamon_value_points p
     set value_e4 = public.div_round_half_even(p.value_e4::numeric * 3, 2)
    from public.nexamon_cards k
   where k.card_key = p.card_key and k.set_key = 'prismatic_peak';

  update public.nexamon_listings l
     set price_cents = public.nexamon_ai_ask_cents(public.nexamon_copy_value_cents(k.value_e4, c.condition, c.grade))
    from public.nexamon_copies c, public.nexamon_cards k
   where l.seller_ai is not null and c.id = l.copy_id and k.card_key = l.card_key and k.set_key = 'prismatic_peak';

  -- The next nexamon_sync() reads the catalogue again: cards that never moved land exactly on their new start price.
  insert into public.nexamon_meta (id, catalogue_hash, synced_at, peak_scaled_at)
  values (true, null, null, now())
  on conflict (id) do update set catalogue_hash = null, peak_scaled_at = excluded.peak_scaled_at;
end
$$;

-- ===== supabase/migrations/20261204005800_nexamon_profile.sql =====
-- =============================================================================
-- NEXA · 5800 · Nexamon: a player's collectibles on their profile (ADR-165)
-- =============================================================================
-- get_player_nexamon(p_nickname, p_limit) is the public view of a collection, like get_collection() for artworks
-- and get_property() for the home: every signed-in player may read it, by nickname (null = the caller's own).
-- It returns the collection in numbers (copies, different cards, value, slabs, tens), the progress per set and one
-- row per card the player owns with its best copy (the most valuable one: condition, grade, serial, value) and
-- the number of copies, most valuable first. p_limit caps the rows (1..500, default all); the numbers always
-- cover the whole collection. A player below the Nexamon level has nothing to show (unlocked false, no cards).
-- Listings, prices asked and gradings in progress stay private: a copy at ASP shows as the raw card it still is.
-- Read only: nothing is written, so the function is STABLE.
-- Idempotent: runs unchanged as supabase/updates/20261204005800_nexamon_profile.sql.

create or replace function public.get_player_nexamon(p_nickname text default null, p_limit integer default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg        jsonb := public.nexamon_cfg();
  v_player   uuid := public.require_player();
  v_target   uuid;
  v_nick     text;
  v_unlocked boolean;
  v_limit    integer := least(greatest(coalesce(p_limit, 500), 1), 500);
  v_summary  jsonb;
  v_sets     jsonb;
  v_cards    jsonb;
begin
  if p_nickname is null then
    v_target := v_player;
  else
    select p.id into v_target from public.profiles p where lower(p.nickname) = lower(btrim(p_nickname));
  end if;
  select p.nickname into v_nick from public.profiles p where p.id = v_target;
  if v_nick is null then
    perform public.api_error('player_not_found');
  end if;
  v_unlocked := public.nexamon_unlocked(v_target);

  with own as (
    select c.card_key, c.serial, c.condition, c.grade, k.set_key, k.number, k.rarity,
           public.nexamon_copy_value_cents(k.value_e4, c.condition, c.grade) as value_cents
      from public.nexamon_copies c join public.nexamon_cards k on k.card_key = c.card_key
     where c.owner_id = v_target and v_unlocked
  ), per_card as (
    -- the best copy of every card: the most valuable, then the higher grade, then the lower serial
    select distinct on (o.card_key)
           o.card_key, o.set_key, o.number, o.rarity, o.serial, o.condition, o.grade, o.value_cents,
           count(*) over (partition by o.card_key) as copies,
           (sum(o.value_cents) over (partition by o.card_key))::bigint as total_cents
      from own o
     order by o.card_key, o.value_cents desc, o.grade desc nulls last, o.serial
  )
  select jsonb_build_object(
           'copies', (select count(*) from own),
           'distinct', (select count(*) from per_card),
           'total', (select count(*) from public.nexamon_cards k where k.in_catalogue),
           'value_cents', (select coalesce(sum(o.value_cents), 0)::bigint from own o),
           'graded', (select count(*) from own o where o.grade is not null),
           'tens', (select count(*) from own o where o.grade = 10)),
         (select coalesce(jsonb_agg(jsonb_build_object(
                   'key', s.set_key, 'cards', s.cards,
                   'distinct', (select count(*) from per_card p where p.set_key = s.set_key),
                   'copies', (select count(*) from own o where o.set_key = s.set_key))
                   order by (cfg #>> array['sets', s.set_key, 'packPriceCents'])::bigint nulls last, s.set_key), '[]'::jsonb)
            from (select k.set_key, count(*) as cards from public.nexamon_cards k where k.in_catalogue group by k.set_key) s),
         (select coalesce(jsonb_agg(jsonb_build_object(
                   'card_key', x.card_key, 'set', x.set_key, 'number', x.number, 'rarity', x.rarity, 'copies', x.copies,
                   'serial', x.serial, 'condition', x.condition, 'grade', x.grade, 'value_cents', x.value_cents,
                   'total_cents', x.total_cents)
                   order by x.value_cents desc, x.set_key, x.number), '[]'::jsonb)
            from (select p.* from per_card p order by p.value_cents desc, p.set_key, p.number limit v_limit) x)
    into v_summary, v_sets, v_cards;

  return jsonb_build_object(
    'nickname', v_nick, 'is_me', v_target = v_player, 'unlocked', v_unlocked,
    'summary', v_summary, 'sets', v_sets, 'cards', v_cards, 'server_time', public.game_now());
end;
$$;
comment on function public.get_player_nexamon(text, integer) is
  'RPC: the Nexamon collection of a player by nickname (null = the caller) for their profile (ADR-165): '
  '{nickname, is_me, unlocked, summary: {copies, distinct, total, value_cents, graded, tens}, sets: [{key, cards, '
  'distinct, copies}], cards: [{card_key, set, number, rarity, copies, serial, condition, grade, value_cents, '
  'total_cents}] (best copy per card, most valuable first, at most p_limit, 1..500), server_time}. Empty for a '
  'player below the Nexamon level; error player_not_found.';

revoke all on function public.get_player_nexamon(text, integer) from public, anon;
grant execute on function public.get_player_nexamon(text, integer) to authenticated, service_role;

commit;
